      if (k === n - 1 && Math.hypot(wp[k][0] - s.x, wp[k][1] - s.z) < 2.5) { done = true; break; }
      still = t > 6 && Math.abs(s.v) < 0.3 ? still + 1 : 0;
      if (still > 30) break;
    }
    return { done, k, n, bad, first, t: +t.toFixed(1), x: +s.x.toFixed(1), z: +s.z.toFixed(1), v: +s.v.toFixed(2) };
  };

